import type { AgentContract, AgentGlobalTarget } from '../types'
import { contractSlug } from './contracts'
import { safePathSegment } from './folders'

const GENERATED_HEADER =
  '<!-- Generated by Prompt Keeper. Source of truth: instructions/**/*.contract.md. Global projection is one-way; manual edits will be reported as drift. -->'

export function globalTargetById(
  targets: AgentGlobalTarget[],
  id: string,
): AgentGlobalTarget | undefined {
  return targets.find((target) => target.id === id)
}

export function globalPathIsValid(path: string): boolean {
  const trimmed = path.trim()
  if (!trimmed) return false
  if (!trimmed.startsWith('~') && !trimmed.startsWith('/')) return false
  if (trimmed.includes('\n')) return false
  return true
}

/** dir 模式：目录 + slug + 扩展名；file 模式：直接使用完整文件路径 */
export function resolveGlobalPath(contract: AgentContract, target: AgentGlobalTarget): string {
  if (target.pathMode === 'file') return target.path
  const dir = target.path.replace(/\/+$/, '')
  const fileName = `${safePathSegment(contractSlug(contract), contract.id)}${target.fileExt ?? '.md'}`
  return `${dir}/${fileName}`
}

export function globalTargetSupports(contract: AgentContract, target: AgentGlobalTarget): boolean {
  const mode = contract.activation.mode
  if (mode === 'glob') return target.supports.globs
  if (mode === 'model') return target.supports.modelDecision
  if (mode === 'manual') return target.supports.manual
  return true
}

function cursorFrontmatter(contract: AgentContract): string[] {
  const lines = ['---']
  const description = contract.activation.description || contract.description
  if (description) lines.push(`description: ${JSON.stringify(description)}`)
  const globs = contract.activation.globs.join(', ')
  if (globs) lines.push(`globs: ${JSON.stringify(globs)}`)
  lines.push(`alwaysApply: ${contract.activation.mode === 'always'}`)
  lines.push('---')
  return lines
}

/** 单契约在全局目标中的原生内容 */
export function compileGlobalContract(target: AgentGlobalTarget, contract: AgentContract): string {
  const body = contract.body.trim()
  if (target.format === 'cursor-mdc') {
    return [...cursorFrontmatter(contract), '', GENERATED_HEADER, '', body, ''].join('\n')
  }
  if (target.format === 'windsurf-rule') {
    return body
  }
  return body
}

function mergedBlock(target: AgentGlobalTarget, contract: AgentContract): string {
  const imports =
    target.supports.imports && contract.imports.length
      ? `${contract.imports.map((path) => `@${path}`).join('\n')}\n\n`
      : ''
  return [
    `<!-- pk:begin ${contract.id} -->`,
    `## ${contract.title}`,
    '',
    `${imports}${contract.body.trim()}`,
    `<!-- pk:end ${contract.id} -->`,
  ].join('\n')
}

/**
 * 生成写入全局目录的文件清单。
 * single-file 目标把多条契约合并进同一个文件；per-contract 目标一契约一文件。
 */
export function compileGlobalFiles(
  target: AgentGlobalTarget,
  contracts: AgentContract[],
): { path: string; content: string }[] {
  if (target.merge === 'per-contract') {
    return contracts.map((contract) => ({
      path: resolveGlobalPath(contract, target),
      content: compileGlobalContract(target, contract),
    }))
  }

  const blocks = contracts.map((contract) => mergedBlock(target, contract))
  const content = blocks.length
    ? `${GENERATED_HEADER}\n\n${blocks.join('\n\n')}\n`
    : `${GENERATED_HEADER}\n\n<!-- 当前没有投影到该全局目标的指令。 -->\n`
  return [{ path: target.path, content }]
}

export function globalPathHint(target: AgentGlobalTarget): string {
  return target.pathMode === 'file'
    ? `这里填写完整文件路径；例如 ${target.defaultPath}。`
    : `这里填写目录；每个契约会生成 <slug>${target.fileExt ?? '.md'}。`
}
